===== src/lib/bmi.ts
     1	export type BmiInput =
     2	  | { units: 'metric'; centimeters: number; kilograms: number }
     3	  | { units: 'imperial'; feet: number; inches: number; pounds: number };
     4	export type BmiResult =
     5	  | {
     6	      ok: true;
     7	      value: number;
     8	      category: 'Underweight' | 'Healthy weight' | 'Overweight' | 'Obesity';
     9	    }
    10	  | { ok: false; error: string };
    11	export function calculateBmi(input: BmiInput): BmiResult {
    12	  const height =
    13	    input.units === 'metric' ? input.centimeters / 100 : (input.feet * 12 + input.inches) * 0.0254;
    14	  const weight = input.units === 'metric' ? input.kilograms : input.pounds * 0.45359237;
    15	  if (
    16	    input.units === 'imperial' &&
    17	    (input.inches < 0 || input.inches >= 12 || !Number.isInteger(input.feet))
    18	  )
    19	    return { ok: false, error: 'Enter whole feet and inches between 0 and 11.9.' };
    20	  if (
    21	    !Number.isFinite(height) ||
    22	    !Number.isFinite(weight) ||
    23	    height < 0.9 ||
    24	    height > 2.5 ||
    25	    weight < 20 ||
    26	    weight > 500
    27	  )
    28	    return {
    29	      ok: false,
    30	      error:
    31	        'Enter a valid adult height (90–250 cm) and weight (20–500 kg), or their imperial equivalents.',
    32	    };
    33	  const raw = weight / (height * height);
    34	  return {
    35	    ok: true,
    36	    value: Math.round(raw * 10) / 10,
    37	    category:
    38	      raw < 18.5
    39	        ? 'Underweight'
    40	        : raw < 25
    41	          ? 'Healthy weight'
    42	          : raw < 30
    43	            ? 'Overweight'
    44	            : 'Obesity',
    45	  };
    46	}
