    29	    const el = dialog.current;
    30	    if (state) {
    31	      setStep(initialStep);
    32	      el?.showModal();
    33	    } else el?.close();
    34	    return () => {
    35	      el?.close();
    36	    };
    37	  }, [state, initialStep]);
    38	  useEffect(() => {
    39	    if (!state) return;
    40	    const prior = document.body.style.overflow;
    41	    document.body.style.overflow = 'hidden';
    42	    return () => {
    43	      document.body.style.overflow = prior;
    44	    };
    45	  }, [state]);
