    95	            <p className="eyebrow">Care in your language</p>
    96	            <h2 id="dialog-title">Let’s get started.</h2>
    97	            <p>Choose the care you’re looking for.</p>
    98	            <form
    99	              key={state?.kind === 'consultation' ? (state.treatment ?? 'default') : 'closed'}
   100	              onSubmit={(e) => {
