     6	export function ServiceCarousel({
     7	  items,
     8	  initialIndex = 0,
     9	}: {
    10	  items: readonly Service[];
    11	  initialIndex?: number;
    12	}) {
    13	  const track = useRef<HTMLDivElement>(null);
    14	  const [position, setPosition] = useState({ start: true, end: false, index: 0 });
    15	  function measure() {
    16	    const el = track.current;
    17	    if (!el) return;
    18	    const cards = Array.from(el.children) as HTMLElement[];
    19	    const first = cards[0];
    20	    const index = first
    21	      ? cards.reduce(
    22	          (nearest, card, i) =>
    23	            Math.abs(card.offsetLeft - first.offsetLeft - el.scrollLeft) <
    24	            Math.abs(cards[nearest].offsetLeft - first.offsetLeft - el.scrollLeft)
    25	              ? i
    26	              : nearest,
    27	          0,
    28	        )
    29	      : 0;
    30	    setPosition({
    31	      start: el.scrollLeft < 2,
    32	      end: el.scrollLeft + el.clientWidth >= el.scrollWidth - 2,
    33	      index,
    34	    });
    35	  }
    36	  useEffect(() => {
    37	    const el = track.current;
    38	    if (!el) return;
    39	    const card = el.children[initialIndex] as HTMLElement | undefined;
    40	    if (card && el.firstElementChild)
    41	      el.scrollLeft = card.offsetLeft - (el.firstElementChild as HTMLElement).offsetLeft;
    42	    measure();
    43	    const observer = new ResizeObserver(measure);
    44	    observer.observe(el);
    45	    return () => observer.disconnect();
    46	  }, [initialIndex]);
    47	  function move(direction: number) {
    48	    const el = track.current;
    49	    if (!el) return;
    50	    const first = el.firstElementChild as HTMLElement | null;
    51	    if (!first) return;
    52	    const width = first.offsetWidth + (parseFloat(getComputedStyle(el).columnGap) || 0);
    53	    el.scrollBy({
    54	      left: direction * width,
    55	      behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches
    56	        ? 'instant'
    57	        : 'smooth',
    58	    });
    59	  }
    60	  return (
    61	    <section
    62	      className="services section"
    63	      aria-roledescription="carousel"
    64	      aria-label="Care services"
    65	    >
    66	      <div className="section-heading">
    67	        <h2>
    68	          Completely online
    69	          <br />
    70	          on your schedule
    71	        </h2>
    72	        <div className="flex gap-3">
    73	          <button
    74	            className="icon-button"
    75	            aria-label="Previous service"
    76	            disabled={position.start}
    77	            onClick={() => move(-1)}
    78	          >
    79	            <ArrowLeft />
    80	          </button>
    81	          <button
