  font-display: swap;
}
@font-face {
  font-family: Syne;
  src: url('/fonts/syne.ttf') format('truetype');
  font-style: normal;
  font-weight: 400 800;
  font-display: swap;
}
@theme {
  --color-forest: #172e20;
  --color-leaf: #39755a;
  --color-cream: #faf9f6;
  --color-mint: #d4fceb;
  --color-pink: #fae0fc;
  --color-aqua: #d8fcfc;
  --font-sans: 'Work Sans', sans-serif;
  --font-heading: 'Work Sans', sans-serif;
}
:root {
  --forest: #172e20;
