.hero-shell {
  margin: 32px 28px 0;
  padding: 24px 28px 28px;
  border-radius: 32px;
  background: white;
}
.header {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  min-height: 64px;
  padding: 12px 24px;
  background: var(--paper);
  border-radius: 999px;
  box-shadow: 0 4px 20px #2925150c;
  z-index: 5;
}
.logo {
  font-family: Arial, sans-serif;
  font-size: 38px;
  line-height: 1;
  letter-spacing: -3px;
  font-weight: 700;
}
.desktop-nav {
  display: flex;
  align-items: center;
  gap: 32px;
  margin-left: auto;
  white-space: nowrap;
  font-size: 18px;
}
.desktop-nav a:hover {
  color: var(--leaf);
}
.header-actions {
  display: flex;
  gap: 16px;
  margin-left: 80px;
}
.header-actions .button {
  font-size: 18px;
  min-height: 48px;
  padding: 10px 30px;
}
.menu-toggle,
.mobile-nav {
  display: none;
}
.hero {
  text-align: center;
  padding: 82px 20px 54px;
}
.hero-badges {
  display: flex;
  gap: 24px;
  justify-content: center;
  flex-wrap: wrap;
  font-size: 14px;
  color: var(--leaf);
  margin-bottom: 24px;
}
.hero-badges span {
  display: flex;
  align-items: center;
  gap: 8px;
}
.hero-badges svg {
  width: 18px;
  height: 18px;
  stroke-width: 1.3;
}
.hero h1 {
  font-size: 68px;
  letter-spacing: -1.5px;
  line-height: 1.15;
  max-width: 920px;
  margin: 0 auto 24px;
}
.hero p {
  white-space: pre-line;
  color: #404640;
  line-height: 1.6;
  margin-bottom: 26px;
}
.hero .button {
  min-height: 56px;
}
.languages {
  margin: 32px auto 0;
  max-width: 1090px;
  overflow: hidden;
  mask-image: linear-gradient(to right, transparent, #000 12%, #000 88%, transparent);
}
.languages > div {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 16px;
  width: max-content;
  position: relative;
  left: 50%;
  transform: translateX(-50%);
}
.languages span {
  white-space: nowrap;
  font-size: 16px;
  line-height: 1.3;
  min-width: 108px;
  padding: 11px 22px;
  border-radius: 100px;
  border: 1px solid #cbd8cf;
  background: var(--paper);
  color: #505a52;
}
.languages span.selected {
  background: #c1dccb;
}
.treatment-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
}
.mint {
  background: var(--color-mint);
}
.pink {
  background: var(--color-pink);
}
.aqua {
  background: var(--color-aqua);
}
.treatment-card {
  position: relative;
  min-height: 420px;
  border-radius: 16px;
  padding: 24px;
