  box-shadow: var(--shadow);
}
.treatment-card .eyebrow {
  color: #263c30;
  margin-bottom: 18px;
}
.treatment-card h3 {
  font-family: var(--font-sans);
  font-size: 24px;
  line-height: 1.17;
  font-weight: 450;
