import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';
const url = process.argv[2] || 'http://127.0.0.1:3100/';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto(url, { waitUntil: 'networkidle' });
const res = {};
for (let w = 320; w <= 1920; w += 10) {
  await page.setViewportSize({ width: w, height: 900 });
  await page.waitForTimeout(20);
  const r = await page.evaluate(() => {
    const out = [];
    const inter = (a, b) => Math.max(0, Math.min(a.right, b.right) - Math.max(a.left, b.left)) * Math.max(0, Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top));
    for (const card of document.querySelectorAll('.treatment-card')) {
      const c = card.getBoundingClientRect();
      const h = card.querySelector('h3').getBoundingClientRect();
      const b = card.querySelector('.button').getBoundingClientRect();
      if (inter(h, b) > 0) out.push(`${card.querySelector('.eyebrow').textContent}: heading/button overlap`);
      if (h.bottom > c.bottom || b.bottom > c.bottom) out.push(`${card.querySelector('.eyebrow').textContent}: content escapes card`);
    }
    // generic text overlap check among text leafs in main sections
    const texts = [...document.querySelectorAll('main h1, main h2, main h3, main p, main .button, main li, main blockquote, footer p, footer a, footer button')].filter(e => e.offsetParent && !e.closest('[aria-hidden="true"],.sr-only,dialog'));
    const rects = texts.map(e => [e, e.getBoundingClientRect()]);
    for (let i = 0; i < rects.length; i++) for (let j = i + 1; j < rects.length; j++) {
      const [e1, r1] = rects[i], [e2, r2] = rects[j];
      if (e1.contains(e2) || e2.contains(e1)) continue;
      if (inter(r1, r2) > 4) out.push(`text overlap: "${e1.textContent.trim().slice(0,25)}" x "${e2.textContent.trim().slice(0,25)}"`);
    }
    return out;
  });
  for (const x of r) (res[x] ||= []).push(w);
}
for (const [k, ws] of Object.entries(res)) console.log(k, ws.length > 6 ? `${ws[0]}..${ws.at(-1)} (${ws.length})` : ws.join(','));
await browser.close();
EOF
