import type { CSSProperties, ReactNode } from 'react';
/**
 * Infinite horizontal ticker. The item list is rendered twice and the track slides by
 * exactly one copy, so the loop is seamless. The second copy is hidden from assistive
 * technology. Hover pauses the motion; `prefers-reduced-motion` renders a static,
 * wrapped list instead, so no item is ever clipped.
 */
export function Marquee({
  items,
  label,
  direction = 'left',
  seconds = 40,
  hidden = false,
  className = '',
}: {
  items: readonly { key: string; content: ReactNode; className?: string }[];
  label?: string;
  direction?: 'left' | 'right';
  seconds?: number;
  /** Hide the whole ticker from assistive technology (e.g. a repeated row). */
  hidden?: boolean;
  className?: string;
}) {
  const group = (copy: boolean) => (
    <ul className="marquee-group" aria-hidden={copy || undefined} aria-label={copy ? undefined : label}>
      {items.map((item) => (
        <li key={item.key} className={item.className}>
          {item.content}
        </li>
      ))}
    </ul>
  );
  return (
    <div
      className={`marquee ${className}`}
      data-direction={direction}
      aria-hidden={hidden || undefined}
      style={{ '--marquee-duration': `${seconds}s` } as CSSProperties}
    >
      <div className="marquee-track">
        {group(false)}
        {group(true)}
      </div>
    </div>
  );
}

