/* Tickers: two identical groups slide by one group width for a seamless loop. */
.marquee {
  overflow: hidden;
}
.marquee-track {
  display: flex;
  width: max-content;
  animation: marquee var(--marquee-duration, 40s) linear infinite;
}
.marquee[data-direction='right'] .marquee-track {
  animation-direction: reverse;
}
.marquee:hover .marquee-track {
  animation-play-state: paused;
}
.marquee-group {
  display: flex;
  flex-shrink: 0;
  gap: var(--marquee-gap, 16px);
  padding: 0 var(--marquee-gap, 16px) 0 0;
  margin: 0;
  list-style: none;
}
@keyframes marquee {
  to {
    transform: translateX(-50%);
  }
}
/* Wide enough to show every trust signal: hold still, as the desktop design does. */
@media (min-width: 1360px) {
  .trust-strip .marquee-track {
    animation: none;
    width: 100%;
  }
  .trust-strip .marquee-group {
    width: 100%;
    justify-content: center;
    padding: 0;
  }
  .trust-strip .marquee-group[aria-hidden] {
    display: none;
  }
}
/* Reduced motion: a static list that wraps, so nothing is left clipped off-screen. */
@media (prefers-reduced-motion: reduce) {
  .marquee-track {
    width: 100%;
  }
  .marquee-group {
    width: 100%;
    flex-wrap: wrap;
    justify-content: center;
    row-gap: 12px;
    padding: 0 16px;
  }
  .marquee-group[aria-hidden],
  .marquee[aria-hidden] {
    display: none;
  }
  .languages {
    mask-image: none;
  }
}

