/**
 * Serializable contracts for a future `GET /v1/home` response.
 * Plain JSON only — no React or transport concerns — and the UI never branches on a
 * specific `id` value: every variation is described by a field below.
 */
export type TreatmentId = 'weight-loss' | 'birth-control' | 'sleep';
/** Brand background family for a treatment; the client maps it to a color token. */
export type Tone = 'mint' | 'pink' | 'aqua';
/** Icons travel as names, never markup; the client owns the icon set. */
export type IconName = 'globe' | 'stethoscope' | 'truck' | 'message' | 'map-pin' | 'headphones';
export interface ImageAsset {
  src: string;
  alt: string;
  width: number;
  height: number;
}
export interface Money {
  /** Integer minor units (cents), so prices never pass through floating point. */
  amountMinor: number;
  currency: 'USD';
  interval: 'month';
}
export interface Language {
  /** BCP 47 tag, e.g. `es`, `zh-Hans`. The value sent back in requests. */
  code: string;
  /** Endonym shown to users, e.g. `Español`. */
  name: string;
}
export interface IconLabel {
  icon: IconName;
  label: string;
}
/** In-page anchor; the home page is the only route so far. */
export interface Link {
  label: string;
  href: `#${string}`;
}
export interface Treatment {
  id: TreatmentId;
  /** Category name on the hero card and in the consultation picker. */
  label: string;
  /** Short name used in navigation and the footer. */
  shortLabel: string;
  /** Hero-card headline and artwork. */
  summary: string;
  cardImage: ImageAsset;
  /** Optional eyebrow above the section title. */
  eyebrow?: string;
  title: string;
  description?: string;
  benefits: readonly string[];
  tone: Tone;
  /** Section portrait, and which side of the copy it sits on at desktop widths. */
  image: ImageAsset;
  imageSide: 'start' | 'end';
  /** Optional floating card over the portrait. */
  imageCallout?: { title: string; subtitle: string; badge: string };
  price?: Money;
  ctaLabel: string;
  /** Self-check offered next to this treatment's plans. */
  eligibilityCheck?: 'bmi';
}
export interface Product {
  id: string;
  treatmentId: TreatmentId;
  name: string;
  price: Money;
  image: ImageAsset;
  /** Caption over the image, e.g. when the artwork is not the exact product. */
  imageNote?: string;
}
export interface CareLayer {
  id: string;
  title: string;
  description: string;
  benefits: readonly string[];
}
export interface Service {
  id: string;
  title: string;
  image: ImageAsset;
  /** Full-bleed photos need light text; product cut-outs sit on white. */
  surface: 'light' | 'dark';
}
export interface Testimonial {
  id: string;
  name: string;
  location: string;
  treatment: string;
  quote: string;
  rating: 1 | 2 | 3 | 4 | 5;
  /** When present, the card renders as a portrait instead of a quote. */
  image?: ImageAsset;
}
export interface Faq {
  id: string;
  question: string;
  answer: string;
}
export interface LegalDocument {
  id: 'terms' | 'privacy' | 'medication-safety';
  title: string;
  summary: string;
}
export interface HomeContent {
  navigation: readonly Link[];
  hero: {
    title: string;
    emphasis: string;
    description: string;
    badges: readonly IconLabel[];
    /** Language codes drawn with the highlighted chip style. */
    highlightedLanguages: readonly Language['code'][];
  };
  languages: readonly Language[];
  treatments: readonly Treatment[];
  products: readonly Product[];
  trustSignals: readonly IconLabel[];
  careLayers: readonly CareLayer[];
  services: readonly Service[];
  testimonials: readonly Testimonial[];
  faqs: readonly Faq[];
  legal: { documents: readonly LegalDocument[]; disclaimer: string };
}
/** No personal or medical data is submitted by this frontend demo. */
export interface ConsultationRequest {
  treatmentId: TreatmentId;
  languageCode: Language['code'];
}
export type ConsultationResult = { status: 'demo'; reference: string };

