import {
  Globe2,
  Headphones,
  MapPinned,
  MessageCircle,
  Stethoscope,
  Truck,
  type LucideProps,
} from 'lucide-react';
import type { IconName } from '../data/contracts';
/** Maps the API's icon names to the client's icon set; icons are always decorative here. */
const icons = {
  globe: Globe2,
  stethoscope: Stethoscope,
  truck: Truck,
  message: MessageCircle,
  'map-pin': MapPinned,
  headphones: Headphones,
} satisfies Record<IconName, unknown>;
export function Icon({ name, ...props }: { name: IconName } & LucideProps) {
  const Symbol = icons[name];
  return <Symbol aria-hidden="true" {...props} />;
}

