import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';
const base = 'http://127.0.0.1:6107';
const idx = await (await fetch(base + '/index.json')).json();
const stories = Object.values(idx.entries).filter(e => e.type === 'story');
const b = await chromium.launch();
for (const s of stories) {
  const p = await b.newPage({ viewport: { width: 1280, height: 900 } });
  const errs = [];
  p.on('pageerror', e => errs.push(e.message));
  p.on('console', m => { if (m.type() === 'error') errs.push(m.text().slice(0, 160)); });
  await p.goto(`${base}/iframe.html?id=${s.id}&viewMode=story`, { waitUntil: 'networkidle' });
  await p.waitForTimeout(500);
  const txt = (await p.locator('#storybook-root').innerText().catch(() => '')).length;
  console.log(errs.length ? 'ERR ' : 'ok  ', s.id, 'text', txt, errs.join(' | '));
  await p.close();
}
await b.close();
EOF
node sb.mjs

